objective.code:
model.setObjective(
    quicksum(Prices[p] * batches[p] for p in range(P))
    - quicksum(
        MachineCosts[m] * quicksum(TimeRequired[m][p] * batches[p] for p in range(P))
        for m in range(M)
    ),
    GRB.MAXIMIZE
)

constraints.code:
for m in range(M):
    model.addConstr(
        sum(TimeRequired[m][p] * batches[p] for p in range(P)) <= Availability[m]
    )
